const target = msg.metadata.target;

if (!target || !target.api_key || !target.client_specific.chatroom_name) {
    node.error("WaSOS not configured on this connection");
    return null;
}

const base = global.get("parat_bridge").base_urls.wasos;
const room = target.client_specific.chatroom_name;

if (msg._multipart) {
    msg.url = base + "/api/v1/chat/messages/" + room;
    msg.headers["x-api-key"] = target.api_key;
} else {
    msg.url = base + "/api/chat/messages/" + room;
    msg.headers = {
        "x-api-key": target.api_key,
        "Content-Type": "application/json"
    };
}

return msg;
